    @Test
    public void testGetTextWithAndWithoutLineReturns() {
        // Arrange: Create a Cell
        Cell cell = new Cell(0, 0, 100, 100);

        // Arrange: Create TextChunks with specific coordinates and text
        // Chunk 1: Top line (Top = 10)
        TextChunk chunk1 = new TextChunk(10, 10, 80, 10);
        chunk1.setText("Hello");

        // Chunk 2: Bottom line (Top = 30), logically distinct vertical line
        TextChunk chunk2 = new TextChunk(30, 10, 80, 10);
        chunk2.setText("World");

        // Arrange: Populate the cell with elements
        // We add them in reverse order to ensure the method's internal sort() logic is triggered
        List<TextChunk> textElements = new ArrayList<>();
        textElements.add(chunk2);
        textElements.add(chunk1);
        
        // Note: Assuming setTextElements exists as implied by the class structure 
        // (Cell extending a container) to allow populating the internal 'textElements' list used in the focal method.
        cell.setTextElements(textElements);

        // Act & Assert 1: useLineReturns = true
        // Expectation: Elements sorted by position ("Hello" then "World"). 
        // Since chunk2.getTop() (30) > chunk1.getTop() (10), a carriage return should be inserted.
        String resultWithReturns = cell.getText(true);
        assertEquals("Should include carriage return for vertically separated chunks", "Hello\rWorld", resultWithReturns);

        // Act & Assert 2: useLineReturns = false
        // Expectation: Elements sorted, but simply concatenated without carriage returns.
        String resultWithoutReturns = cell.getText(false);
        assertEquals("Should concatenate text without carriage returns", "HelloWorld", resultWithoutReturns);
        
        // Act & Assert 3: Verify trim behavior
        // If the resulting string had whitespace, the focal method ends with .trim()
        TextChunk chunkSpace = new TextChunk(50, 10, 80, 10);
        chunkSpace.setText(" ");
        List<TextChunk> spaceElements = new ArrayList<>();
        spaceElements.add(chunkSpace);
        cell.setTextElements(spaceElements);
        
        assertEquals("Should return empty string if content is only whitespace due to trim", "", cell.getText(true));
    }
